/**
 * Sage Architecture Visualizer - Modular Rough.js Sketchify Engine
 *
 * Intercepts SVG elements generated by Mermaid and replaces standard geometric
 * shapes with hand-drawn, architectural sketches using high-density hachure fills.
 */

(function (global) {
  'use strict';

  // =========================================================================
  // VISUAL TUNING PARAMETERS
  // TWEAK HERE: Adjust these variables to customize sketchiness and fill density.
  // =========================================================================
  const DEFAULT_SKETCH_CONFIG = {
    // roughness: 0.0 = geometric lines, 1.3 = hand-drawn pencil, 2.5 = very sketchy
    roughness: 1.3,
    // bowing: Curvature/deviation of straight lines (higher = more wobble)
    bowing: 1.2,
    // strokeWidth: Minimum stroke thickness for sketchy outlines
    strokeWidth: 1.5,
    // fillStyle: 'hachure', 'cross-hatch', 'zigzag', 'dots', 'dashed', or 'solid'
    fillStyle: 'hachure',
    // fillWeight: Thickness of hachure lines (1.0 = crisp lines)
    fillWeight: 1.0,
    // hachureGap: Spacing between lines (3px = dense, high-clarity fill)
    hachureGap: 3,
    // seed: Random seed for deterministic sketchy rendering across reloads
    seed: 7
  };

  /**
   * Checks if a CSS color value represents a transparent/empty color.
   */
  function isClear(color) {
    return !color || color === 'none' || color === 'transparent' || /rgba\([^)]*,\s*0\)$/.test(color);
  }

  /**
   * Extracts Rough.js drawing options from computed styles or attributes.
   * Prioritizes CSS stylesheet cascade over presentation attributes to preserve
   * Mermaid node class palette colors (e.g. :::blue, :::green).
   *
   * @param {Object} computedStyle - Computed style or style object of element
   * @param {Object} [config] - Sketch configuration overrides
   * @param {string} [tagName] - Tag name of element (e.g., 'rect', 'line')
   * @param {number} [seed] - Optional random seed
   * @returns {Object} Rough.js options object
   */
  function extractRoughOptions(computedStyle, config, tagName, seed) {
    const cfg = Object.assign({}, DEFAULT_SKETCH_CONFIG, config || {});

    const cs = computedStyle || {};
    const stroke = (cs.stroke && !isClear(cs.stroke)) ? cs.stroke : 'none';
    const fill = (cs.fill && !isClear(cs.fill)) ? cs.fill : 'none';
    const strokeWidth = parseFloat(cs.strokeWidth) || cfg.strokeWidth;

    const hasStroke = !isClear(stroke);
    const hasFill = tagName !== 'line' && !isClear(fill) && cfg.fillStyle !== 'none';

    const markerEnd = cs.markerEnd || cs['marker-end'] || '';
    const markerStart = cs.markerStart || cs['marker-start'] || '';
    const hasMarker = (markerEnd && markerEnd !== 'none') || (markerStart && markerStart !== 'none');

    const opt = {
      roughness: cfg.roughness,
      bowing: cfg.bowing,
      stroke: hasStroke ? stroke : 'none',
      strokeWidth: Math.max(cfg.strokeWidth, strokeWidth),
      fill: hasFill ? fill : undefined,
      fillStyle: cfg.fillStyle,
      fillWeight: cfg.fillWeight,
      hachureGap: cfg.hachureGap,
      seed: seed !== undefined ? seed : cfg.seed,
      // Disable multi-stroke when markers exist so connector arrowheads align cleanly
      disableMultiStroke: hasMarker
    };

    if (cs.strokeDasharray && cs.strokeDasharray !== 'none') {
      opt.strokeLineDash = cs.strokeDasharray.split(/[\s,]+/).map(parseFloat).filter(function (n) { return !isNaN(n); });
    }

    return opt;
  }

  /**
   * Parses numerical attribute safely.
   */
  function parseAttr(el, name) {
    return parseFloat(el.getAttribute(name)) || 0;
  }

  /**
   * Replaces Mermaid SVG shapes with sketchy twins rendered via Rough.js.
   *
   * @param {SVGElement} svg - Root SVG container from Mermaid
   * @param {Object} [options] - Optional parameter overrides matching DEFAULT_SKETCH_CONFIG
   * @param {Object} [roughInstance] - Optional custom Rough.js SVG instance (useful for testing)
   * @returns {SVGElement} The processed SVG container
   */
  function sketchify(svg, options, roughInstance) {
    if (!svg) return svg;

    // Resolve Rough.js SVG engine
    const roughCanvas = roughInstance || (typeof rough !== 'undefined' && rough.svg ? rough.svg(svg) : null);
    if (!roughCanvas) {
      console.warn('Rough.js library is not available');
      return svg;
    }

    const config = Object.assign({}, DEFAULT_SKETCH_CONFIG, options || {});
    let seedCounter = config.seed;

    // Query candidate shapes to sketchify
    const elements = svg.querySelectorAll('rect, polygon, circle, ellipse, line, path');

    elements.forEach(function (el) {
      // Guard against double sketchification and protect text labels & marker defs
      if (el.closest && el.closest('[data-sketchy="true"], defs, marker, .edgeLabel, foreignObject, .labelBkg, text, tspan')) {
        return;
      }

      // Compute element style prioritizing CSS cascade over presentation attributes
      const domStyle = typeof window !== 'undefined' && window.getComputedStyle ? window.getComputedStyle(el) : (el.style || {});
      const strokeAttr = el.getAttribute ? el.getAttribute('stroke') : null;
      const fillAttr = el.getAttribute ? el.getAttribute('fill') : null;
      const strokeWidthAttr = el.getAttribute ? el.getAttribute('stroke-width') : null;
      const markerEndAttr = el.getAttribute ? el.getAttribute('marker-end') : null;
      const markerStartAttr = el.getAttribute ? el.getAttribute('marker-start') : null;
      const dashAttr = el.getAttribute ? el.getAttribute('stroke-dasharray') : null;

      const styleObj = {
        stroke: (domStyle.stroke && !isClear(domStyle.stroke)) ? domStyle.stroke : strokeAttr,
        fill: (domStyle.fill && !isClear(domStyle.fill)) ? domStyle.fill : fillAttr,
        strokeWidth: strokeWidthAttr || domStyle.strokeWidth,
        markerEnd: markerEndAttr || domStyle.markerEnd,
        markerStart: markerStartAttr || domStyle.markerStart,
        strokeDasharray: dashAttr || domStyle.strokeDasharray
      };

      const shapeOpt = extractRoughOptions(styleObj, config, el.tagName, seedCounter++);

      // Skip elements that are completely invisible
      if (shapeOpt.stroke === 'none' && shapeOpt.fill === undefined) {
        return;
      }

      let twin = null;

      switch (el.tagName) {
        case 'rect': {
          const w = parseAttr(el, 'width');
          const h = parseAttr(el, 'height');
          if (w > 0 && h > 0) {
            twin = roughCanvas.rectangle(parseAttr(el, 'x'), parseAttr(el, 'y'), w, h, shapeOpt);
          }
          break;
        }
        case 'polygon': {
          const rawPoints = (el.getAttribute('points') || '').trim().split(/[\s,]+/).map(Number);
          const points = [];
          for (let k = 0; k < rawPoints.length - 1; k += 2) {
            points.push([rawPoints[k], rawPoints[k + 1]]);
          }
          if (points.length >= 3) {
            twin = roughCanvas.polygon(points, shapeOpt);
          }
          break;
        }
        case 'circle': {
          const r = parseAttr(el, 'r');
          if (r > 0) {
            twin = roughCanvas.circle(parseAttr(el, 'cx'), parseAttr(el, 'cy'), r * 2, shapeOpt);
          }
          break;
        }
        case 'ellipse': {
          const rx = parseAttr(el, 'rx');
          const ry = parseAttr(el, 'ry');
          if (rx > 0 && ry > 0) {
            twin = roughCanvas.ellipse(parseAttr(el, 'cx'), parseAttr(el, 'cy'), rx * 2, ry * 2, shapeOpt);
          }
          break;
        }
        case 'line': {
          twin = roughCanvas.line(parseAttr(el, 'x1'), parseAttr(el, 'y1'), parseAttr(el, 'x2'), parseAttr(el, 'y2'), shapeOpt);
          break;
        }
        case 'path': {
          const d = el.getAttribute('d');
          if (d) {
            twin = roughCanvas.path(d, shapeOpt);
          }
          break;
        }
      }

      if (twin) {
        // Tag group as sketchy twin to prevent recursive reprocessing
        if (twin.setAttribute) {
          twin.setAttribute('data-sketchy', 'true');
        }

        // Preserve any coordinate transformations
        const transform = el.getAttribute ? el.getAttribute('transform') : null;
        if (transform && twin.setAttribute) {
          twin.setAttribute('transform', transform);
        }

        // Propagate connector arrow markers to sketchy paths
        ['marker-end', 'marker-start'].forEach(function (markerName) {
          const markerVal = el.getAttribute ? el.getAttribute(markerName) : styleObj[markerName];
          if (markerVal && markerVal !== 'none' && twin.querySelectorAll) {
            twin.querySelectorAll('path').forEach(function (p) {
              if (p.setAttribute) p.setAttribute(markerName, markerVal);
            });
          }
        });

        // Insert sketchy twin right before the original shape and hide original
        if (el.parentNode && el.parentNode.insertBefore) {
          el.parentNode.insertBefore(twin, el);
          if (el.style) {
            el.style.display = 'none';
          }
        }
      }
    });

    return svg;
  }

  // Export for browser and CommonJS (Node.js testing)
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      DEFAULT_SKETCH_CONFIG: DEFAULT_SKETCH_CONFIG,
      extractRoughOptions: extractRoughOptions,
      sketchify: sketchify
    };
  } else {
    global.DEFAULT_SKETCH_CONFIG = DEFAULT_SKETCH_CONFIG;
    global.extractRoughOptions = extractRoughOptions;
    global.sketchify = sketchify;
  }

})(typeof window !== 'undefined' ? window : this);
